#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."

APP="build/US-HR Settings Panel.app"

swift build -c release --product USHRSettingsPanel --arch arm64
BIN="$(swift build -c release --product USHRSettingsPanel --arch arm64 --show-bin-path)/USHRSettingsPanel"

rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp "$BIN" "$APP/Contents/MacOS/USHRSettingsPanel"
cp Resources/Info.plist "$APP/Contents/Info.plist"

# App icon. Release builds (--release) always use the project's own icon
# (Resources/AppIcon.icns, generated by scripts/make-icon.swift). Local builds use
# TASCAM's original icon when the old TASCAM app bundle is present in the repo root
# (git-ignored, never committed or distributed), otherwise the project icon.
TASCAM_ICON="US-HR_SettingsPanel.app/Contents/Resources/icon.icns"
if [[ "${1:-}" != "--release" && -f "$TASCAM_ICON" ]]; then
    cp "$TASCAM_ICON" "$APP/Contents/Resources/AppIcon.icns"
else
    cp Resources/AppIcon.icns "$APP/Contents/Resources/AppIcon.icns"
fi

codesign --force --options runtime -s - "$APP"
codesign --verify --strict "$APP"
echo "Built $APP"
